using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates overlapped block motion compensation and local warped motion on two real six-frame
/// 128x128 AV1/IVF clips (a rotating, zooming and panning pattern encoded by aomenc at a speed
/// setting that selects these tools). The first clip enables only OBMC: blocks with the OBMC motion
/// mode re-predict their top and left regions from the neighbours' motion vectors and blend them by
/// the overlap masks. The second enables OBMC, local warped motion and global motion together: WARP
/// blocks derive an affine model from their same-reference edge neighbours and are predicted by the
/// warp kernel. Every decoded frame's planes must be exactly equal to dav1d's decoded output.
/// </summary>
public class Av1WarpedMotionDecodeTests
{
    private const string ObmcClipIvfBase64 =
        "";

    private const string CombinedClipIvfBase64 =
        "";

    private static readonly string[] ObmcLumaBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] ObmcUBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] ObmcVBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] CombinedLumaBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] CombinedUBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] CombinedVBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    [Fact]
    public void DecodeAllFrames_ObmcClip_MatchesDav1dExactly()
        => DecodeAndCompare(ObmcClipIvfBase64, ObmcLumaBase64, ObmcUBase64, ObmcVBase64);

    [Fact]
    public void DecodeAllFrames_WarpObmcGlobalMotionClip_MatchesDav1dExactly()
        => DecodeAndCompare(CombinedClipIvfBase64, CombinedLumaBase64, CombinedUBase64, CombinedVBase64);

    private static void DecodeAndCompare(string ivfBase64, string[] lumaBase64, string[] uBase64, string[] vBase64)
    {
        using MemoryStream stream = new(Convert.FromBase64String(ivfBase64));
        List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(6, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            Assert.Equal(Convert.FromBase64String(lumaBase64[i]), Crop(frames[i].Luma));
            Assert.Equal(Convert.FromBase64String(uBase64[i]), Crop(frames[i].ChromaU));
            Assert.Equal(Convert.FromBase64String(vBase64[i]), Crop(frames[i].ChromaV));
        }
    }

    private static byte[] Crop(Av1Plane plane)
    {
        byte[] result = new byte[plane.CropWidth * plane.CropHeight];
        for (int y = 0; y < plane.CropHeight; y++)
        {
            plane.Samples.AsSpan(y * plane.Width, plane.CropWidth).CopyTo(result.AsSpan(y * plane.CropWidth));
        }

        return result;
    }
}
